package com.codepilot1c.core.edt.development;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
import java.nio.file.*;import java.util.*;import java.io.*;import java.util.zip.*;import java.net.URI;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
public class NativePackageServiceTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 static final byte[] DLL="owned-native-fixture".getBytes(java.nio.charset.StandardCharsets.UTF_8);
 static String digest(byte[] data)throws Exception{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(data));}
 static byte[] zip(String path,String arch)throws Exception{var bytes=new ByteArrayOutputStream();try(var z=new ZipOutputStream(bytes)){for(var e:Map.of("manifest.xml",("<bundle xmlns=\"http://v8.1c.ru/8.2/addin/bundle\"><component os=\"Windows\" path=\"AgentHostNative.dll\" type=\"native\" arch=\""+arch+"\"/></bundle>").getBytes(),path,DLL,"SDK-LICENSE",new byte[]{1},"LICENSE",new byte[]{2}).entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}return bytes.toByteArray();}
 static NativePackageService.Descriptor descriptor(byte[] bytes)throws Exception{return new NativePackageService.Descriptor("v1.4.0.fixture",digest(bytes),digest(DLL),List.of("screenshot_png"));}
 NativePackageService service(Path root,byte[] bytes,AtomicInteger calls)throws Exception{return new NativePackageService(root,descriptor(bytes),(u,p,c)->{calls.incrementAndGet();Files.write(p,bytes);});}
 @Test public void verifiedCacheIsReusedAcrossInstancesWithoutNetwork()throws Exception{byte[] bytes=zip("AgentHostNative.dll","x86_64");Path root=temp.newFolder().toPath();var calls=new AtomicInteger();var s=service(root,bytes,calls);assertEquals(false,s.status().get("ready"));var first=s.ensure(()->false,p->{});assertEquals(false,first.get("cache_hit"));assertEquals(true,service(root,bytes,calls).ensure(()->false,p->{}).get("cache_hit"));assertEquals(1,calls.get());assertArrayEquals(bytes,Files.readAllBytes(s.archive()));}
 @Test public void hashFailureNeverPublishesPartialArchive()throws Exception{byte[] bytes=zip("AgentHostNative.dll","x86_64");var s=new NativePackageService(temp.newFolder().toPath(),descriptor(bytes),(u,p,c)->Files.writeString(p,"corrupt"));assertThrows(IOException.class,()->s.ensure(()->false,p->{}));assertEquals(false,s.status().get("ready"));assertFalse(Files.exists(s.archive()));try(var files=Files.list(s.archive().getParent())){assertEquals(0,files.count());}}
 @Test public void offlineFailureKeepsRetryPossible()throws Exception{byte[] bytes=zip("AgentHostNative.dll","x86_64");Path root=temp.newFolder().toPath();var s=new NativePackageService(root,descriptor(bytes),(u,p,c)->{throw new IOException("offline");});assertThrows(IOException.class,()->s.ensure(()->false,p->{}));assertEquals(true,service(root,bytes,new AtomicInteger()).ensure(()->false,p->{}).get("ready"));}
 @Test public void editedCacheIsPreservedDuringVerifiedRepair()throws Exception{byte[] bytes=zip("AgentHostNative.dll","x86_64");Path root=temp.newFolder().toPath();var s=service(root,bytes,new AtomicInteger());Files.writeString(s.archive(),"edited");assertEquals("invalid_cache",s.status().get("state"));assertEquals(true,s.ensure(()->false,p->{}).get("ready"));try(var files=Files.list(root.resolve("preserved"))){var saved=files.toList();assertEquals(1,saved.size());assertEquals("edited",Files.readString(saved.get(0)));}}
 @Test public void archiveNamesAndArchitectureAreValidatedEvenWithMatchingHash()throws Exception{for(byte[] bytes:List.of(zip("../AgentHostNative.dll","x86_64"),zip("AgentHostNative.dll","ARM64"))){var s=service(temp.newFolder().toPath(),bytes,new AtomicInteger());assertThrows(Exception.class,()->s.ensure(()->false,p->{}));assertFalse(Files.exists(s.archive()));}}
 @Test public void concurrentWarmupAndMcpPrepareDownloadOnce()throws Exception{byte[] bytes=zip("AgentHostNative.dll","x86_64");Path root=temp.newFolder().toPath();var count=new AtomicInteger();var entered=new CountDownLatch(1);var gate=new CountDownLatch(1);var s=new NativePackageService(root,descriptor(bytes),(u,p,c)->{count.incrementAndGet();entered.countDown();gate.await(3,TimeUnit.SECONDS);Files.write(p,bytes);});var other=service(root,bytes,count);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->s.ensure(()->false,p->{}));assertTrue(entered.await(2,TimeUnit.SECONDS));var b=pool.submit(()->other.ensure(()->false,p->{}));gate.countDown();assertEquals(true,a.get(5,TimeUnit.SECONDS).get("ready"));assertEquals(true,b.get(5,TimeUnit.SECONDS).get("ready"));assertEquals(1,count.get());}finally{gate.countDown();pool.shutdownNow();}}
 @Test public void cancellationCannotPublishArtifact()throws Exception{byte[] bytes=zip("AgentHostNative.dll","x86_64");var stopped=new java.util.concurrent.atomic.AtomicBoolean();var s=new NativePackageService(temp.newFolder().toPath(),descriptor(bytes),(u,p,c)->{Files.write(p,bytes);stopped.set(true);});assertThrows(IOException.class,()->s.ensure(stopped::get,p->{}));assertFalse(Files.exists(s.archive()));}
 @Test public void redirectOriginsAreBounded(){assertTrue(NativePackageService.allowedDownload(URI.create("https://release-assets.githubusercontent.com/file?signature=transient")));for(String u:List.of("http://github.com/file","https://evil.test/file","https://github.com.evil.test/file","https://user@github.com/file","https://github.com:444/file"))assertFalse(NativePackageService.allowedDownload(URI.create(u)));}
 @Test public void descriptorPinsCurrentNativeSources()throws Exception{var d=NativePackageService.bundled();assertEquals("screenshot_png",d.features().get(0));var r=Path.of("native/agent-host");var files=new ArrayList<Path>();files.add(r.resolve("AgentHost.cpp"));files.add(r.resolve("agent-host.def"));try(var headers=Files.list(r.resolve("include"))){headers.filter(p->p.toString().endsWith(".h")).sorted().forEach(files::add);}var text=new StringBuilder();for(Path f:files){byte[] bytes=Files.readString(f).replace("\r\n","\n").getBytes(java.nio.charset.StandardCharsets.UTF_8);text.append(r.relativize(f).toString().replace('\\','/')).append('\n').append(digest(bytes)).append('\n');}try(var in=NativePackageService.class.getResourceAsStream("/resources/agent-host/native-package.json")){var json=com.google.gson.JsonParser.parseString(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();assertEquals(json.get("native_sources_sha256").getAsString(),digest(text.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));}}
 @Test public void customPackageArgumentsRemainExplicitAndUnmodified()throws Exception{var a=Map.<String,Object>of("native_path","custom.zip","expected_native_sha256","a".repeat(64));assertSame(a,NativePackageManager.getInstance().resolve(a));assertThrows(IllegalArgumentException.class,()->NativePackageManager.getInstance().resolve(Map.of("native_path","only.zip")));}
}
